    int stock{5};
    std::stack<int> history;
    history.push(stock);
    stock += 3;
    std::cout << stock << '\n';
    if (!history.empty()) { stock = history.top(); history.pop(); }
    std::cout << stock << ' ' << history.empty() << '\n';
}

