#include <iostream>
#include <stack>
#include <queue>
int main() {
    int n{};
    if (!(std::cin >> n) || n < 0 || n > 100) { std::cout << "invalid\n"; return 0; }
    std::stack<int> stack;
    std::queue<int> queue;
    for (int i = 0; i < n; ++i) {
        int value{};
        if (!(std::cin >> value) || value < -1000 || value > 1000) { std::cout << "invalid\n"; return 0; }
        stack.push(value); queue.push(value);
    }
    std::cin >> std::ws;
    if (!std::cin.eof()) { std::cout << "invalid\n"; return 0; }
    bool first{true};
    while (!stack.empty()) { if (!first) { std::cout << ' '; } std::cout << stack.top(); stack.pop(); first = false; }
    std::cout << '\n';
    first = true;
    while (!queue.empty()) { if (!first) { std::cout << ' '; } std::cout << queue.front(); queue.pop(); first = false; }
    std::cout << '\n';
}

