#ifndef NEXUS_CATALOG_HPP
#define NEXUS_CATALOG_HPP
#include <string>
#include <vector>
struct Item { int id{}; int stock{}; };
enum class Kind { add, remove, undo, list, exportFile };
struct Command { Kind kind{Kind::list}; int id{}; int amount{}; };
bool applyCommand(std::vector<Item>& items, const Command& command);
bool parseCommand(const std::string& line, Command& command);
bool loadCatalog(const std::string& path, std::vector<Item>& items);
bool saveCatalog(const std::string& path, const std::vector<Item>& items);
#endif

starterFiles.src/domain.cpp:
#include "catalog.hpp"
bool applyCommand(std::vector<Item>& items, const Command& command) {
    if (command.amount < 0 || command.amount > 1000) { return false; }
    for (Item& item : items) {
        if (item.id != command.id) { continue; }
        if (command.kind == Kind::add) {
            if (command.amount > 1000 - item.stock) { return false; }
            item.stock += command.amount;
            return true;
        }
        if (command.kind == Kind::remove) {
            if (command.amount > item.stock) { return false; }
            item.stock -= command.amount;
            return true;
        }
        return false;
    }
    return false;
}

