#include "catalog.hpp"
#include <fstream>
#include <sstream>
bool parseCommand(const std::string& line, Command& command) {
    std::istringstream input{line};
    std::string name;
    if (!(input >> name)) { return false; }
    Command candidate;
    if (name == "add" || name == "remove") {
        candidate.kind = name == "add" ? Kind::add : Kind::remove;
        if (!(input >> candidate.id >> candidate.amount) || candidate.id < 1 || candidate.id > 1000 || candidate.amount < 0 || candidate.amount > 1000) { return false; }
    } else if (name == "undo") { candidate.kind = Kind::undo; }
    else if (name == "list") { candidate.kind = Kind::list; }
    else if (name == "export") { candidate.kind = Kind::exportFile; }
    else { return false; }
    input >> std::ws;
    if (!input.eof()) { return false; }
    command = candidate;
    return true;
}
bool loadCatalog(const std::string& path, std::vector<Item>& items) {
    std::ifstream input{path};
    std::string line;
    if (!std::getline(input, line) || line != "NEXUS_CATALOG_V1") { return false; }
    std::vector<Item> candidate;
    while (std::getline(input, line)) {
        if (line.size() > 200 || candidate.size() == 10) { return false; }
        std::istringstream parser{line};
        Item item;
        if (!(parser >> item.id >> item.stock) || item.id < 1 || item.id > 1000 || item.stock < 0 || item.stock > 1000) { return false; }
        parser >> std::ws;
        if (!parser.eof()) { return false; }
        for (const Item& old : candidate) { if (old.id == item.id) { return false; } }
        candidate.push_back(item);
    }
    if (input.bad() || (!input.eof() && input.fail())) { return false; }
    items = candidate;
    return true;
}
bool saveCatalog(const std::string& path, const std::vector<Item>& items) {
    std::ofstream output{path};
    output << "NEXUS_CATALOG_V1\n";
    for (const Item& item : items) { output << item.id << ' ' << item.stock << '\n'; }
    output.close();
    return bool(output);
}

