#include <iostream>
#include "catalog.hpp"
#include <fstream>
#include <queue>
#include <stack>
int main() {
    std::ifstream probe{"catalog.txt"};
    if (!probe) { std::cout << "missing\n"; return 0; }
    probe.close();
    std::vector<Item> items;
    if (!loadCatalog("catalog.txt", items)) { std::cout << "invalid\n"; return 0; }
    std::queue<Command> commands;
    std::string line;
    while (std::getline(std::cin, line)) {
        Command command;
        if (commands.size() == 50 || line.size() > 200 || !parseCommand(line, command)) { std::cout << "invalid\n"; return 0; }
        commands.push(command);
    }
    if (std::cin.bad()) { std::cout << "invalid\n"; return 0; }
    std::stack<std::vector<Item>> history;
    while (!commands.empty()) {
        Command command = commands.front();
        commands.pop();
        if (command.kind == Kind::list) {
            for (std::size_t i = 0; i < items.size(); ++i) { if (i != 0) { std::cout << ' '; } std::cout << items[i].id << ':' << items[i].stock; }
            std::cout << '\n';
        } else if (command.kind == Kind::undo) {
            if (history.empty()) { std::cout << "empty-history\n"; }
            else { items = history.top(); history.pop(); std::cout << "undone\n"; }
        } else if (command.kind == Kind::exportFile) {
            if (!saveCatalog("catalog-out.txt", items)) { std::cout << "write-error\n"; return 0; }
            std::cout << "exported\n";
        } else {
            auto candidate = items;
            if (!applyCommand(candidate, command)) { std::cout << "rejected\n"; }
            else { history.push(items); items = candidate; std::cout << "ok\n"; }
        }
    }
}

