#include <iostream>
#include "catalog.hpp"
int main() {
    std::vector<Item> items{{1, 5}};
    int failures{};
    if (!applyCommand(items, Command{Kind::add, 1, 3}) || items[0].stock != 8) { ++failures; }
    if (applyCommand(items, Command{Kind::remove, 1, 9}) || items[0].stock != 8) { ++failures; }
    if (!applyCommand(items, Command{Kind::remove, 1, 8}) || items[0].stock != 0) { ++failures; }
    if (applyCommand(items, Command{Kind::add, 9, 1}) || items[0].stock != 0) { ++failures; }
    if (applyCommand(items, Command{Kind::add, 1, -1}) || items[0].stock != 0) { ++failures; }
    Command command;
    if (!parseCommand("add 1 2", command) || command.id != 1 || command.amount != 2) { ++failures; }
    if (parseCommand("add 1 2 x", command)) { ++failures; }
    if (parseCommand("undo x", command)) { ++failures; }
    if (failures) { std::cout << "FAIL\n"; return 1; }
    std::cout << "PASS 8\n";
}
